/// <summary>
/// NS Zelinka 29.02.24
/// Sets the enabled property on the action pane buttons.
/// </summary>
protected void setButtonEnabled()
{
    next setButtonEnabled();

    this.AVAtoggleProjectCreationButtons();
}

/// <summary>
/// NS Zelinka 29.02.24
/// set control access
/// </summary>
private void AVAtoggleProjectCreationButtons()
{
    KCS_PTMToolTable    kcs_PTMToolTable;
    WrkCtrTable         wrkCtrTable;

    boolean             enabledProjectCreationPP;
    boolean             enabledProjectCreationSP;

    boolean             locProjProductionExist;
    boolean             locProjMaintenanceExist;

    kcs_PTMToolTable            = this.listPage().activeRecord(queryDataSourceStr(AVAPTMToolTableListPage, KCS_PTMToolTable)) as KCS_PTMToolTable;

    wrkCtrTable = wrkCtrTable::find(kcs_PTMToolTable.ToolId);

    enabledProjectCreationPP    = kcs_PTMToolTable.AVAICProjProd           == '';
    enabledProjectCreationSP    = kcs_PTMToolTable.AVAICProjMaintenance    == '';

    if(kcs_PTMToolTable.RecId)
    {
        locProjProductionExist  = kcs_PTMToolTable.avaICProjProductionExist();
        locProjMaintenanceExist = kcs_PTMToolTable.avaICProjMaintenanceExist();
    }

    /*
    this.listPage().actionPaneControlEnabled(
        formControlStr(AVAPTMToolTableListPage, AVAProjectCreationPP), enabledProjectCreationPP);
    this.listPage().actionPaneControlEnabled(
        formControlStr(AVAPTMToolTableListPage, AVAProjectCreationSP), enabledProjectCreationSP);
    */
    // Creation
    this.listPage().actionPaneControlEnabled(
        formControlStr(AVAPTMToolTableListPage, AVAProjectCreationPP), !locProjProductionExist);
    this.listPage().actionPaneControlEnabled(
        formControlStr(AVAPTMToolTableListPage, AVAProjectCreationSP), !locProjMaintenanceExist);
    // Inquiries
    this.listPage().actionPaneControlEnabled(   formControlStr(AVAPTMToolTableListPage, AVAProductionProject),
                                                locProjProductionExist                                          );
    this.listPage().actionPaneControlEnabled(   formControlStr(AVAPTMToolTableListPage, AVAServiceProject),
                                                locProjMaintenanceExist                                         );

    this.listPage().actionPaneControlEnabled(formControlStr(AVAPTMToolTableListPage, AVAWrkCtrDateCalendar), wrkCtrTable.RecId);
}
